                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="34" name="question_34" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="34" name="question_34" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="34" name="question_34" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="34" name="question_34" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="34" name="question_34" value="E"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-35" class="ielts-q-badge">35</strong> <span>He worked for the benefit of specific groups of people.</span></td>
