-- Section 1522: Reading Passage 2: Should we try to bring extinct species back to life?
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1522, 152, 'reading', 'Reading Passage 2: Should we try to bring extinct species back to life?', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-17                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>The Reading Passage has six paragraphs, <strong>A-F</strong>.</p>
<p>Which paragraph contains the following information?</p>
<p><em>Write the correct letter, <strong>A-F</strong>, in boxes on your answer sheet.</em></p>
<p><strong><em>NB</em></strong><em>   You may use any letter more than once.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
