INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1523, 152, 'reading', 'Reading Passage 3: Having a laugh', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-31                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</p>
<p><em>Write the correct letter in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title"><span>When referring to laughter in the first paragraphs, the writer emphasises</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> its impact on language.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> its function in human culture.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> its value to scientific research.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> its universality in animal societies.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title"><span>What does the writer suggest about Charley Douglass?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> He understood the importance of enjoying humour in a group setting.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> He believed that TV viewers at home needed to be told when to laugh.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> He wanted his shows to appeal to audiences across the social spectrum.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> He preferred shows where audiences were present in the recording studio.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title"><span>What makes the Santa Cruz study particularly significant?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> the various different types of laughter that were studied</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> the similar results produced by a wide range of cultures</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> the number of different academic disciplines involved</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> the many kinds of people whose laughter was recorded</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title"><span>Which of the following happened in the San Diego study?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> Some participants became very upset.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> Participants exchanged roles.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> Participants who had not met before became friends.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> Some participants were unable to laugh.</span></label></div></div><div class="ielts-standalone-q" data-qnum="31"><div class="ielts-q-header"><strong class="ielts-q-badge">31</strong><span class="ielts-q-title"><span>In the fifth paragraph, what did the results of the San Diego study suggest?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="A"><span class="ielts-radio-text"><strong>A</strong> It is clear whether a dominant laugh is produced by a high- or low-status person.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="B"><span class="ielts-radio-text"><strong>B</strong> Low-status individuals in a position of power will still produce submissive laughs.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="C"><span class="ielts-radio-text"><strong>C</strong> The submissive laughs of low- and high-status individuals are surprisingly similar.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="D"><span class="ielts-radio-text"><strong>D</strong> High-status individuals can always be identified by their way of laughing.</span></label></div></div></div>
