-- Section 1532: Reading Passage 2: The Desolenator: producing clean water
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1532, 153, 'reading', 'Reading Passage 2: The Desolenator: producing clean water', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-20                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>The Reading Passage has nine paragraphs, <strong>A-H</strong></p>
<p>Choose the correct heading for each section from the list of headings below</p>
<p><em>Write the correct number, <strong>i-x</strong>, in boxes on your answer sheet.</em></p>
<p><strong>List of Headings</strong></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                                                                                        <div class="ielts-headings-group mb-6">
  <div class="bg-slate-50 border border-slate-200 rounded-xl p-3 mb-4 space-y-1">
    <div class="text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">List of Headings:</div>
    <div class="text-xs text-slate-700"><strong>i.</strong> Getting the finance for production</div><div class="text-xs text-slate-700"><strong>ii.</strong> An unexpected benefit</div><div class="text-xs text-slate-700"><strong>iii.</strong> From initial inspiration to new product</div><div class="text-xs text-slate-700"><strong>iv.</strong> The range of potential customers for the device</div><div class="text-xs text-slate-700"><strong>v.</strong> What makes the device different from alternatives</div><div class="text-xs text-slate-700"><strong>vi.</strong> Cleaning water from a range of sources</div><div class="text-xs text-slate-700"><strong>vii.</strong> Overcoming production difficulties</div><div class="text-xs text-slate-700"><strong>viii.</strong> Profit not the primary goal</div><div class="text-xs text-slate-700"><strong>ix.</strong> A warm welcome for the device</div><div class="text-xs text-slate-700"><strong>x.</strong> The number of people affected by water shortages</div>
  </div>
